=== CMakePresets ===
{
  "version": 3,
  "configurePresets": [
    {
      "name": "Default",
      "binaryDir": "${sourceDir}/build",
      "installDir": "${sourceDir}/dist",
      "cacheVariables": {
        "CMAKE_BUILD_TYPE": "Release",
        "CMAKE_MSVC_RUNTIME_LIBRARY": "MultiThreaded"
      }
    },
    {
      "name": "CPU",
      "inherits": ["Default"]
    },
    {
      "name": "CUDA",
      "inherits": ["Default"]
    },
    {
      "name": "CUDA 11",
      "inherits": ["CUDA"],
      "cacheVariables": {
        "CMAKE_CUDA_ARCHITECTURES": "37-virtual;50-virtual;60-virtual;61-virtual;70-virtual;75-virtual;80-virtual;86-virtual",
        "CMAKE_CUDA_FLAGS": "-Wno-deprecated-gpu-targets -t 2"
      }
    },
    {
      "name": "CUDA 11 K80",
      "inherits": ["CUDA"],
      "cacheVariables": {
        "CMAKE_CUDA_ARCHITECTURES": "37-real;50-real;52-real;60-real;61-real;70-real;75-real;80-real;86-real",
        "CMAKE_CUDA_FLAGS": "-Wno-deprecated-gpu-targets -t 2"
      }
    },
    {
      "name": "CUDA 12",
      "inherits": ["CUDA"],
      "cacheVariables": {
        "CMAKE_CUDA_ARCHITECTURES": "50;52;60;61;70;75;80;86;89;90;90a;120",
        "CMAKE_CUDA_FLAGS": "-Wno-deprecated-gpu-targets -t 2"
      }
    },
    {
      "name": "CUDA 13",
      "inherits": ["CUDA"],
      "cacheVariables": {
        "CMAKE_CUDA_ARCHITECTURES": "75-virtual;80-virtual;86-virtual;87-virtual;89-virtual;90-virtual;90a-virtual;100-virtual;103-virtual;110-virtual;120-virtual;121-virtual",
        "CMAKE_CUDA_FLAGS": "-t 2"
      }
