      "name": "JetPack 6",
      "inherits": ["CUDA"],
      "cacheVariables": {
        "CMAKE_CUDA_ARCHITECTURES": "87"
      }
    },
    {
      "name": "ROCm",
      "inherits": ["Default"],
      "cacheVariables": {
        "CMAKE_HIP_PLATFORM": "amd"
      }
    },
    {
      "name": "ROCm 6",
      "inherits": ["ROCm"],
      "cacheVariables": {
        "CMAKE_HIP_FLAGS": "-parallel-jobs=4",
        "AMDGPU_TARGETS": "gfx940;gfx941;gfx942;gfx1010;gfx1012;gfx1030;gfx1100;gfx1101;gfx1102;gfx1151;gfx1200;gfx1201;gfx908:xnack-;gfx90a:xnack+;gfx90a:xnack-"
      }
    },
    {
      "name": "Vulkan",
      "inherits": ["Default"]
    }
  ],
  "buildPresets": [
    {
      "name": "Default",
      "configurePreset": "Default",
      "configuration": "Release"
    },
    {
      "name": "CPU",
      "configurePreset": "Default",
      "targets": ["ggml-cpu"]
    },
    {
      "name": "CUDA",
      "configurePreset": "CUDA",
      "targets": ["ggml-cuda"]
    },
    {
      "name": "CUDA 11",
      "inherits": ["CUDA"],
      "configurePreset": "CUDA 11"
    },
    {
      "name": "CUDA 11 K80",
      "inherits": ["CUDA"],
      "configurePreset": "CUDA 11 K80"
    },
    {
      "name": "CUDA 12",
      "inherits": ["CUDA"],
      "configurePreset": "CUDA 12"
    },
    {
      "name": "CUDA 13",
      "inherits": ["CUDA"],
      "configurePreset": "CUDA 13"
    },
    {
      "name": "JetPack 5",
      "inherits": ["CUDA"],
      "configurePreset": "JetPack 5"
    },
    {
      "name": "JetPack 6",
      "inherits": ["CUDA"],
      "configurePreset": "JetPack 6"
    },
    {
      "name": "ROCm",
      "configurePreset": "ROCm",
      "targets": ["ggml-hip"]
    },
    {
      "name": "ROCm 6",
      "inherits": ["ROCm"],
      "configurePreset": "ROCm 6"
    },
    {
      "name": "Vulkan",
      "targets": ["ggml-vulkan"],
      "configurePreset": "Vulkan"
    }
  ]
