1	/**
2	 * Deterministic output check (port of cicd/scripts/lib/simple_check.sh, plus the
3	 * two jq sentinels the models suite carries in TC-MODELS-003).
4	 *
5	 * Three ways to fail, all cheap and model-free: empty output, output with no
6	 * letters or digits in it (REPLY_NO_TEXT), and one short unit repeated to fill
7	 * the reply (REPLY_REPEAT). A failure here gates whether the agent judge is even
8	 * worth running — and the repeat case must never reach it, because a judge asked
9	 * to quote repeated text back loops on it.
10	 *
11	 * Thinking models (qwen3.x, qwen3-vl, deepseek-r1, gemma4) can put coherent
12	 * output entirely in `thinking` while `response` is empty when num_predict caps
13	 * generation early, so either field counts; the checks run on whichever is used.
14	 */
15	export interface ContentVerdict {
16	  pass: boolean;
17	  reason: string;
18	  source: 'response' | 'thinking' | 'none';
19	}
20	
21	/**
22	 * True when `s` is its own first `u` characters repeated, for some unit length
23	 * 1..50. Short strings are exempt (a reply must be at least max(100, 5*u) long)
24	 * so a brief genuine answer is not read as a loop. Mirrors the jq in
25	 * cicd/tests/testcases/models/TC-MODELS-003.yml.
26	 */
27	function isRepeatedUnit(s: string): boolean {
28	  const n = s.length;
29	  for (let u = 1; u <= 50; u++) {
30	    if (n < Math.max(100, 5 * u)) continue;
31	    if (s.slice(0, u).repeat(Math.ceil(n / u) + 1).slice(0, n) === s) return true;
32	  }
33	  return false;
34	}
35	
36	export function simpleContentCheck(response: string, thinking: string): ContentVerdict {
37	  let text: string;
38	  let source: 'response' | 'thinking';
39	  if (response.trim()) {
40	    text = response.trim();
41	    source = 'response';
42	  } else if (thinking.trim()) {
43	    text = thinking.trim();
44	    source = 'thinking';
45	  } else {
46	    return { pass: false, reason: 'both response and thinking are empty/whitespace', source: 'none' };
47	  }
48	
49	  if (!/[\p{L}\p{N}]/u.test(text)) {
50	    return { pass: false, reason: 'no letters or digits in the reply', source };
51	  }
52	  if (isRepeatedUnit(text)) {
53	    return { pass: false, reason: 'one short unit repeated to fill the reply', source };
54	  }
55	
56	  return {
57	    pass: true,
58	    reason: source === 'response' ? 'non-empty response' : 'non-empty thinking (response empty)',
59	    source,
60	  };
61	}

